const OFFLINE_HTML='<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0D4CD3"><title>ФАС торги — нет соединения</title><style>body{margin:0;background:#F5F7FA;color:#0B1F33;font:16px/1.7 system-ui,sans-serif;display:grid;min-height:100vh;place-items:center}main{max-width:380px;background:#fff;margin:24px;padding:32px;border:1px solid #D6E0EA;border-radius:20px}h1{font-size:27px;line-height:1.2}a{display:inline-block;background:#0D4CD3;color:white;padding:12px 20px;border-radius:10px;text-decoration:none}small{color:#53697D}</style><main><small>ФАС ТОРГИ</small><h1>Нет подключения к интернету</h1><p>Подключитесь к сети, чтобы открыть каталог и пройти вход. Данные аккаунта и действия в торгах не сохраняются для работы без сети.</p><a href="./">Попробовать снова</a></main></html>';
function excluded(url){return url.origin!==self.location.origin||url.searchParams.has('token')||url.searchParams.has('code')||url.searchParams.has('state')||url.searchParams.has('access_token')||/\/(api|auth|oauth|login|logout|signin|payment|payments)(\/|$)/i.test(url.pathname)}
function staticType(url){if(url.search&&![...url.searchParams.keys()].every(k=>k==='v'))return null;return STATIC_TYPES.get(url.pathname.replace(/^\//,''))||null}
function mayCache(response,type){const policy=response.headers.get('cache-control')||'',content=response.headers.get('content-type')||'';return response.ok&&response.status===200&&!response.redirected&&response.type!=='opaque'&&!/no-store|private/i.test(policy)&&content.toLowerCase().includes(type)}
// Private hosting marks assets private, so an eager sweep cannot populate this
// public-only cache. Load used assets through the existing fetch handler instead.
self.addEventListener('install',event=>{event.waitUntil((async()=>{try{await caches.open(CACHE_NAME)}catch{/* Browsing must work when Cache Storage is disabled. */}})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{await Promise.all((await caches.keys()).filter(name=>name.startsWith(CACHE_PREFIX)&&name!==CACHE_NAME).map(name=>caches.delete(name)));await self.clients.claim()})())});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||excluded(url))return;
 if(request.mode==='navigate'){event.respondWith(fetch(request).catch(()=>new Response(OFFLINE_HTML,{status:503,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}})));return}
 const type=staticType(url);if(!type)return;
 event.respondWith((async()=>{let response;try{response=await fetch(request)}catch{try{const cache=await caches.open(CACHE_NAME);const cached=await cache.match(request);if(cached&&mayCache(cached,type))return cached}catch{/* Cache Storage may be disabled; preserve the network failure without rejecting. */}return Response.error()}if(mayCache(response,type)){try{const cache=await caches.open(CACHE_NAME);await cache.put(request,response.clone())}catch{/* Storage limits must not block a successful network response. */}}return response})());
});

// A locally generated alert can only open a lot on this Site, through its usual access gate.
self.addEventListener('notificationclick',event=>{
 event.notification.close();
 const lotId=Number(event.notification.data?.lotId);if(!Number.isSafeInteger(lotId)||lotId<=0)return;
 const target=new URL('./',self.registration.scope);target.searchParams.set('lot',String(lotId));
 event.waitUntil((async()=>{
  let windows=[];try{windows=await self.clients.matchAll({type:'window',includeUncontrolled:false})}catch{}
  for(const client of windows){
   let current;try{current=new URL(client.url)}catch{continue}
   if(current.origin!==target.origin||!['/','/index.html'].includes(current.pathname)||typeof client.navigate!=='function')continue;
   try{const opened=await client.navigate(target.href);if(opened){await opened.focus?.();return}}catch{}
  }
  try{await self.clients.openWindow(target.href)}catch{}
 })());
});
